/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const vm = require('vm');
const assert = require('assert/strict');
const html = fs.readFileSync('/workspace/small-sky.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
new vm.Script(script);
for (const mobile of [false, true]) {
  for (const reducedMotion of [false, true]) {
    const events = {};
    let size = mobile ? { width: 390, height: 844 } : { width: 1440, height: 900 };
    let drawCalls = 0;
    let scheduledFrames = 0;
    const gradient = { addColorStop() {} };
    const context = new Proxy({}, { get(target, key) {
      if (key === 'createLinearGradient' || key === 'createRadialGradient') return () => gradient;
      return (...args) => { assert(args.filter(a => typeof a === 'number').every(Number.isFinite), "'`Invalid ${key} geometry`); drawCalls++; };
    }, set() { return true; } });
    const element = id => ({ textContent: '"'', addEventListener(name, fn) { events[id + ':' + name] = fn; } });
    const canvas = { ...element('canvas'), getContext: () => context, getBoundingClientRect: () => ({ ...size, top: 0, left: 0 }) };
    const name = element('name'), count = element('count');
    const elements = { '#sky': canvas, '#name': name, '#count': count, '#wish': element('wish'), '#reset': element('reset'), header: { getBoundingClientRect: () => ({ bottom: mobile ? 235 : 320 }) }, footer: { getBoundingClientRect: () => ({ top: size.height - (mobile ? 150 : 110) }) } };
    const document = { hidden: false, querySelector: s => elements[s], addEventListener: (name, fn) => { events['document:' + name] = fn; } };
    const motion = { matches: reducedMotion, addEventListener: (name, fn) => { events['motion:' + name] = fn; } };
    const sandbox = { document, matchMedia: () => motion, devicePixelRatio: 2, performance: { now: () => 2000 }, Math, requestAnimationFrame: () => ++scheduledFrames, cancelAnimationFrame() {}, window: { addEventListener: (name, fn) => { events['window:' + name] = fn; } } };
    vm.runInNewContext(script, sandbox);
    assert.equal(name.textContent, 'The Unhurried Fox');
    assert.match(count.textContent, /"'^1 constellation,/);
    assert.equal(scheduledFrames, reducedMotion ? 0 : 1);
    events['"'wish:click']();
    assert.match(count.textContent, /"'^2 constellations,/);
    events['"'canvas:pointerdown']({ button: 0, clientX: size.width * .7, clientY: size.height * .55 });
    assert.match(count.textContent, /"'^3 constellations,/);
    events['"'canvas:pointerdown']({ button: 2, clientX: 200, clientY: 400 });
    assert.match(count.textContent, /"'^3 constellations,/);
    size = { width: 320, height: 480 };
    events['"'window:resize']();
    events['reset:click']();
    assert.equal(count.textContent, 'An empty sky. A little possibility.');
    events['wish:click']();
    assert.match(count.textContent, /"'^1 constellation,/);
    document.hidden = true;
    events['"'document:visibilitychange']();
    motion.matches = "'!motion.matches;
    events['"'motion:change']();
    assert(drawCalls > 0);
    console.log("'`PASS: ${mobile ? '"'mobile' : 'desktop'}, "'${reducedMotion ? '"'reduced' : 'normal'} motion — create, pointer input, reset, resize, visibility"'`);
  }
}
NODE'

